def closestFair(n: int) -> int:
    def is_fair(x: int) -> bool:
        odd = even = 0
        for d in str(x):
            if int(d) % 2 == 0:
                even += 1
            else:
                odd += 1
        return odd == even

    digits = len(str(n))
    # If odd number of digits, jump to next even length
    if digits % 2 == 1:
        digits += 1
        n = 10 ** (digits - 1)

    # From n upwards, find the first fair integer
    x = n
    while True:
        if is_fair(x):
            return x
        x += 1
